                let node = capture.node;
                let line = node.start_position().row + 1;

                if capture_name == "import_path" {
                    extract_imports_from_node(&node, source, "", line, imports);
                }
            }
        }
    });

    if timed_out {
        return Err(ParserError::Timeout(tc.micros));
    }

    Ok(())
}

