use tree_sitter::{Parser, Query, QueryCursor, StreamingIterator};

const ELEMENT: &str = r"
(function_definition name: (name) @func_name) @function
(method_declaration name: (name) @method_name) @function
(class_declaration name: (name) @class_name) @class
(interface_declaration name: (name) @class_name) @class
(trait_declaration name: (name) @class_name) @class
(enum_declaration name: (name) @class_name) @class
";
const CALL: &str = r"
(function_call_expression function: [(name) (qualified_name (name))] @call)
(member_call_expression name: (name) @call)
(nullsafe_member_call_expression name: (name) @call)
(scoped_call_expression name: (name) @call)
";
const REFERENCE: &str = r"
(named_type [(name) (qualified_name)] @type_ref)
";
const IMPORT: &str = r"
(namespace_use_declaration) @import_path
";
const DEFUSE: &str = r"
(assignment_expression left: (variable_name (name) @write.assign))
(augmented_assignment_expression left: (variable_name (name) @writeread.update))
(update_expression argument: (variable_name (name) @writeread.update))
(static_variable_declaration name: (variable_name (name) @write.local))
(simple_parameter name: (variable_name (name) @write.local))
(variable_name (name) @read.usage)
";
const IMPLEMENTS_PROBE: &str = r"(class_declaration) @c";

const SRC: &str = r#"<?php
namespace App\Models;
use App\Contracts\HasName;
use App\Base\Model as BaseModel;
use function App\Util\helper;
interface Shape extends Drawable, Named { public function area(): float; }
trait Loggable { public function log(string $m): void { echo $m; } }
enum Suit: string implements HasName { case Hearts = 'H'; public function label(): string { return $this->value; } }
abstract class Dog extends BaseModel implements Barks, \Countable { public function bark() { $this->speak(); self::reset(); Foo::make(); $x = strlen("a"); } }
class Plain { }
function top(int $a, $b = 2): int { $total = $a; $total += $b; $total++; return helper($total) + \strlen("x"); }
?>
<p>html</p>
<?php echo "done";
"#;

fn run(name: &str, lang: &tree_sitter::Language, q: &str, root: tree_sitter::Node, src: &str) {
    let query = match Query::new(lang, q) {
        Ok(q) => q,
        Err(e) => { println!("[{name}] COMPILE ERROR: {e}"); return; }
    };
    println!("[{name}] compiles, {} patterns", query.pattern_count());
    let mut cur = QueryCursor::new();
    let mut ms = cur.matches(&query, root, src.as_bytes());
    while let Some(m) = ms.next() {
        for c in m.captures {
            let cn = query.capture_names()[c.index as usize];
            let t = &src[c.node.start_byte()..c.node.end_byte()];
            println!("  pat{} {}={:?} kind={} parent={}", m.pattern_index, cn, t.replace('\n', " "), c.node.kind(), c.node.parent().map_or("", |p| p.kind()));
        }
    }
}

fn main() {
    let lang: tree_sitter::Language = tree_sitter_php::LANGUAGE_PHP.into();
    let mut p = Parser::new();
    p.set_language(&lang).unwrap();
    let tree = p.parse(SRC, None).unwrap();
    let root = tree.root_node();
    println!("has_error={}", root.has_error());
    fn walk(n: tree_sitter::Node, depth: usize, out: &mut Vec<String>) {
        if n.is_named() && depth <= 4 {
            out.push(format!("{}{} [{}..{}]", "  ".repeat(depth), n.kind(), n.start_byte(), n.end_byte()));
        }
        let mut c = n.walk();
        for ch in n.children(&mut c) { walk(ch, depth + 1, out); }
    }
    if std::env::var("TREE").is_ok() { let mut v = vec![]; walk(root, 0, &mut v); println!("{}", v.join("\n")); }
    run("ELEMENT", &lang, ELEMENT, root, SRC);
    run("CALL", &lang, CALL, root, SRC);
    run("REFERENCE", &lang, REFERENCE, root, SRC);
    run("IMPORT", &lang, IMPORT, root, SRC);
    run("DEFUSE", &lang, DEFUSE, root, SRC);
    let _ = IMPLEMENTS_PROBE;
    // Field walk on class with extends + implements
    let mut stack = vec![root];
    while let Some(n) = stack.pop() {
        if n.kind() == "class_declaration" && n.child_by_field_name("name").map(|x| &SRC[x.start_byte()..x.end_byte()] == "Dog").unwrap_or(false) {
            let mut c = n.walk();
            for ch in n.children(&mut c) {
                println!("Dog child kind={} field_name={:?} text={:?}", ch.kind(), n.field_name_for_child(ch.id() as u32).unwrap_or(""), &SRC[ch.start_byte()..ch.end_byte()].replace('\n'," "));
                let mut c2 = ch.walk();
                for g in ch.named_children(&mut c2) { println!("    named child kind={} text={:?}", g.kind(), &SRC[g.start_byte()..g.end_byte()]); }
            }
        }
        let mut c = n.walk();
        for ch in n.children(&mut c) { stack.push(ch); }
    }
}
