use tree_sitter::{Node, Parser, Query, QueryCursor, StreamingIterator};

const REFERENCE: &str = r"
(named_type [(name) (qualified_name)] @type_ref)
";

fn extract_inheritance(node: &Node, source: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cursor = node.walk();
    for child in node.named_children(&mut cursor) {
        match child.kind() {
            "base_clause" | "class_interface_clause" => {
                let prefix = if child.kind() == "base_clause" { "extends" } else { "implements" };
                let mut c2 = child.walk();
                for name in child.named_children(&mut c2) {
                    if matches!(name.kind(), "name" | "qualified_name" | "relative_name") {
                        out.push(format!("{prefix} {}", &source[name.start_byte()..name.end_byte()]));
                    }
                }
            }
            _ => {}
        }
    }
    out
}

fn main() {
    let lang: tree_sitter::Language = tree_sitter_php::LANGUAGE_PHP.into();
    let mut p = Parser::new();
    p.set_language(&lang).unwrap();
    let src = "<?php\nfunction f(Foo $x, ?\\Bar\\Baz $y): Qux { return new Quux(); }\nclass Dog extends Bar implements A, B {}\nclass Plain {}\ninterface I extends X, Y {}\nenum E: string implements A {}\n";
    let tree = p.parse(src, None).unwrap();
    let root = tree.root_node();
    println!("has_error={}", root.has_error());
    let q = Query::new(&lang, REFERENCE).unwrap();
    let mut cur = QueryCursor::new();
    let mut ms = cur.matches(&q, root, src.as_bytes());
    while let Some(m) = ms.next() {
        for c in m.captures() {
            println!("REF {}={:?} parent={}", q.capture_names()[c.index as usize], &src[c.node.start_byte()..c.node.end_byte()], c.node.parent().unwrap().kind());
        }
    }
    let mut stack = vec![root];
    while let Some(n) = stack.pop() {
        if matches!(n.kind(), "class_declaration" | "interface_declaration" | "enum_declaration") {
            let name = n.child_by_field_name("name").map(|x| &src[x.start_byte()..x.end_byte()]).unwrap_or("");
            println!("{} {} -> {:?}", n.kind(), name, extract_inheritance(&n, src));
        }
        let mut c = n.walk();
        for ch in n.children(&mut c) { stack.push(ch); }
    }
}
